package wbcrud

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/debpalash/OpenGTM/apps/backend-go/internal/canonjson"
)

// Row, query and connector-run cursors (workbooks.py:172-269). The three
// formats are byte-compatible with the Python encoders (vectors generated by
// legacy/python/scripts/gen_cursor_vectors.py), so a cursor Python issued
// mid-pagination keeps working, with one exception: v2 (long value) cursors
// are bound to a scope hash and Go's scope hashes its own SQL, so a v2 cursor
// issued by Python answers "restart pagination".

const (
	msgRowCursor   = "Invalid workbook row cursor"
	msgQueryCursor = "Invalid workbook row cursor; restart pagination"
	msgRunCursor   = "Invalid connector run cursor"

	// maxInlineCursor is the longest v1 cursor; longer ones become v2.
	maxInlineCursor = 512
)

func bad400(detail string) *GuardError { return &GuardError{Status: 400, Detail: detail} }

// OrderTerm is one keyset ordering term. Expr is a SQL expression over
// workbook_rows whose placeholders refer to RowQuery.Args.
type OrderTerm struct {
	Expr string
	Desc bool
}

// CursorScope hashes the view id and ordering identity (sha256 hex).
// RowQuery.Scope additionally binds the filters and workbook.
func CursorScope(view *string, terms []OrderTerm) string {
	return scopeHash(view, "", nil, terms)
}

func scopeHash(view *string, where string, args []any, terms []OrderTerm) string {
	var v any
	if view != nil {
		v = *view
	}
	ts := make([]any, 0, len(terms))
	for _, t := range terms {
		ts = append(ts, []any{t.Expr, t.Desc})
	}
	norm := make([]any, len(args))
	for i, a := range args {
		norm[i] = normalizeValue(a)
	}
	b, _ := canonjson.Marshal([]any{v, where, norm, ts}, true)
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// normalizeValue maps cursor/arg values onto what canonjson accepts.
func normalizeValue(v any) any {
	switch x := v.(type) {
	case int:
		return int64(x)
	case int32:
		return int64(x)
	case json.Number:
		return numberValue(x)
	}
	return v
}

func numberValue(n json.Number) any {
	s := n.String()
	if !strings.ContainsAny(s, ".eE") {
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i
		}
	}
	f, _ := strconv.ParseFloat(s, 64)
	return f
}

// ValuesDigest is _cursor_values_digest.
func ValuesDigest(values []any) string {
	norm := make([]any, len(values))
	for i, v := range values {
		norm[i] = normalizeValue(v)
	}
	b, err := canonjson.Marshal(norm, false)
	if err != nil {
		b = []byte(fmt.Sprint(norm))
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

func encodeB64(b []byte) string { return base64.RawURLEncoding.EncodeToString(b) }

// decodeB64 accepts what Python's urlsafe_b64decode accepts for well-formed
// cursors (padding optional); stray characters are rejected.
func decodeB64(s string) ([]byte, error) {
	s = strings.TrimRight(s, "=")
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' || c == '_') {
			return nil, fmt.Errorf("bad cursor character")
		}
	}
	return base64.RawURLEncoding.DecodeString(s)
}

// decodePayload is base64 + json.loads.
func decodePayload(cursor string) (any, error) {
	raw, err := decodeB64(cursor)
	if err != nil {
		return nil, err
	}
	if !utf8.Valid(raw) {
		return nil, fmt.Errorf("invalid utf-8")
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	if _, err := dec.Token(); err != io.EOF {
		return nil, fmt.Errorf("trailing data")
	}
	return v, nil
}

func jsonCompact(v any) []byte {
	b, _ := canonjson.Marshal(normalizeValue(v), false)
	return b
}

// EncodeRowCursor is _encode_row_cursor.
func EncodeRowCursor(position int, id int64) string {
	return encodeB64([]byte("[" + strconv.Itoa(position) + "," + strconv.FormatInt(id, 10) + "]"))
}

// pyInt mimics int(x) for JSON scalars.
func pyInt(v any) (int64, bool) {
	switch x := v.(type) {
	case json.Number:
		switch n := numberValue(x).(type) {
		case int64:
			return n, true
		case float64:
			if math.IsNaN(n) || math.IsInf(n, 0) || math.Abs(n) >= 1<<62 {
				return 0, false
			}
			return int64(n), true
		}
	case string:
		i, err := strconv.ParseInt(strings.TrimSpace(x), 10, 64)
		return i, err == nil
	case bool:
		if x {
			return 1, true
		}
		return 0, true
	}
	return 0, false
}

// DecodeRowCursor is _decode_row_cursor.
func DecodeRowCursor(cursor string) (int, int64, *GuardError) {
	payload, err := decodePayload(cursor)
	if err != nil {
		return 0, 0, bad400(msgRowCursor)
	}
	arr, ok := payload.([]any)
	if !ok || len(arr) != 2 {
		return 0, 0, bad400(msgRowCursor)
	}
	pos, ok1 := pyInt(arr[0])
	id, ok2 := pyInt(arr[1])
	if !ok1 || !ok2 || pos < 0 || id < 1 || pos > math.MaxInt32 {
		return 0, 0, bad400(msgRowCursor)
	}
	return int(pos), id, nil
}

// EncodeQueryCursor is _encode_workbook_query_cursor: a v1 cursor carrying the
// tuple, or a v2 cursor (row id, scope, digest) when the v1 form exceeds 512
// characters.
func EncodeQueryCursor(values []any, id int64, scope string) string {
	norm := make([]any, len(values))
	for i, v := range values {
		norm[i] = normalizeValue(v)
	}
	vb, _ := canonjson.Marshal(norm, false)
	cursor := encodeB64([]byte(`{"v":1,"values":` + string(vb) + `}`))
	if len(cursor) <= maxInlineCursor {
		return cursor
	}
	sb := jsonCompact(scope)
	db := jsonCompact(ValuesDigest(values))
	return encodeB64([]byte(`{"v":2,"row":` + strconv.FormatInt(id, 10) + `,"scope":` + string(sb) + `,"digest":` + string(db) + `}`))
}

// QueryCursor is a decoded query cursor. For v1 Values holds the tuple. For v2
// Lookup is true: the tuple must be re-read from row RowID and its digest
// compared with Digest (RowQuery.ResolveCursor does that).
type QueryCursor struct {
	Values []any
	Lookup bool
	RowID  int64
	Digest string
}

func isNumber(v any, want int64) bool {
	n, ok := v.(json.Number)
	if !ok {
		return false
	}
	f, err := strconv.ParseFloat(n.String(), 64)
	return err == nil && f == float64(want)
}

func normalizeDecoded(v any) any {
	switch x := v.(type) {
	case json.Number:
		return numberValue(x)
	case []any:
		for i := range x {
			x[i] = normalizeDecoded(x[i])
		}
	case map[string]any:
		for k := range x {
			x[k] = normalizeDecoded(x[k])
		}
	}
	return v
}

// DecodeQueryCursorRaw is _decode_workbook_query_cursor up to (not including)
// the database lookup a v2 cursor needs.
func DecodeQueryCursorRaw(cursor string, expectedTerms int, scope string) (QueryCursor, *GuardError) {
	payload, err := decodePayload(cursor)
	if err != nil {
		return QueryCursor{}, bad400(msgQueryCursor)
	}
	obj, isObj := payload.(map[string]any)
	if isObj && isNumber(obj["v"], 2) {
		n, isNum := obj["row"].(json.Number)
		var row int64
		if isNum && !strings.ContainsAny(n.String(), ".eE") {
			row, err = strconv.ParseInt(n.String(), 10, 64)
		} else {
			err = fmt.Errorf("row not int")
		}
		sc, _ := obj["scope"].(string)
		if err != nil || row < 1 || sc != scope {
			return QueryCursor{}, bad400(msgQueryCursor)
		}
		dg, _ := obj["digest"].(string)
		return QueryCursor{Lookup: true, RowID: row, Digest: dg}, nil
	}
	if !isObj || !isNumber(obj["v"], 1) {
		return QueryCursor{}, bad400(msgRowCursor)
	}
	vals, ok := obj["values"].([]any)
	if !ok || len(vals) != expectedTerms {
		return QueryCursor{}, bad400(msgRowCursor)
	}
	for i := range vals {
		vals[i] = normalizeDecoded(vals[i])
	}
	return QueryCursor{Values: vals}, nil
}

// DecodeQueryCursor decodes a v1 cursor. A v2 cursor needs a database lookup;
// callers use DecodeQueryCursorRaw / RowQuery.ResolveCursor for it, and here it
// answers the restart-pagination 400.
func DecodeQueryCursor(cursor string, expectedTerms int, scope string) ([]any, *GuardError) {
	qc, g := DecodeQueryCursorRaw(cursor, expectedTerms, scope)
	if g != nil {
		return nil, g
	}
	if qc.Lookup {
		return nil, bad400(msgQueryCursor)
	}
	return qc.Values, nil
}

// EncodeConnectorRunCursor is _encode_connector_run_cursor
// ([created_at.isoformat(), id] as a v1 cursor). The offset of createdAt is
// kept as isoformat does, so callers pass created_at.UTC() (pgx returns
// timestamptz values in the process-local zone).
func EncodeConnectorRunCursor(createdAt time.Time, id string) string {
	layout := "2006-01-02T15:04:05-07:00"
	if createdAt.Nanosecond()/1000 != 0 {
		layout = "2006-01-02T15:04:05.000000-07:00"
	}
	iso := createdAt.Truncate(time.Microsecond).Format(layout)
	return encodeB64([]byte(`{"v":1,"values":[` + string(jsonCompact(iso)) + `,` + string(jsonCompact(id)) + `]}`))
}

var isoLayouts = []string{
	"2006-01-02T15:04:05Z07:00", "2006-01-02 15:04:05Z07:00",
	"2006-01-02T15:04:05Z0700", "2006-01-02 15:04:05Z0700",
	"2006-01-02T15:04:05", "2006-01-02 15:04:05",
	"2006-01-02T15:04Z07:00", "2006-01-02T15:04",
	"2006-01-02",
}

// DecodeConnectorRunCursor is _decode_connector_run_cursor; naive timestamps
// are taken as UTC and the result is always in UTC.
func DecodeConnectorRunCursor(cursor string) (time.Time, string, *GuardError) {
	qc, g := DecodeQueryCursorRaw(cursor, 2, "")
	if g != nil || qc.Lookup {
		return time.Time{}, "", bad400(msgRunCursor)
	}
	s, ok1 := qc.Values[0].(string)
	id, ok2 := qc.Values[1].(string)
	if !ok1 || !ok2 {
		return time.Time{}, "", bad400(msgRunCursor)
	}
	for _, l := range isoLayouts {
		if t, err := time.Parse(l, s); err == nil {
			return t.UTC(), id, nil
		}
	}
	return time.Time{}, "", bad400(msgRunCursor)
}
